#pragma once
#include <stdint.h>
// Bevel OS assets. Tables are generated by tools/assets/gen_assets.py from the
// ASCII-art sources in tools/assets/src/ into assets_gen.c.

// Fixed 8x16 text font: the 95 ASCII glyphs (32..126) first, then the accented glyphs
// above ASCII sorted by code, 142 in all. Row byte: bit7 = leftmost pixel.
// Proportional UI font, same glyph order, cell height 12 (row 0 top). Baseline = row 9
// (caps occupy rows 2..9, x-height rows 4..9, descenders rows 10..11). Row word: bit15 =
// leftmost pixel.
#define FONT_UI_H 12
#define FONT_UI_BASELINE 9
#define FONT_NGLYPH 170
extern const uint8_t  font_mono[FONT_NGLYPH][16];
extern const uint8_t  font_ui_adv[FONT_NGLYPH];          // advance in px, INCLUDING 1px inter-glyph gap
extern const uint16_t font_ui_rows[FONT_NGLYPH][FONT_UI_H];
// A code point (0..255) to its row in the tables above; 0xFFFF = these fonts have no glyph for it.
// Text is UTF-8, so a letter above ASCII is 2 bytes and needs this lookup.
extern const uint16_t font_glyph_index[256];
typedef struct { uint8_t w, h; int8_t hot_x, hot_y; const uint8_t *px; } bitmap_t; // px = w*h bytes RGB222, 0xFF = transparent
// 16x16 and 32x32 icons
extern const bitmap_t icon16_folder, icon16_file, icon16_text, icon16_image, icon16_app, icon16_game,
    icon16_drive, icon16_settings, icon16_computer, icon16_terminal, icon16_help, icon16_shutdown,
    icon16_logo, icon16_tasks, icon16_up, icon16_camera, icon16_sound, icon16_refresh;
extern const bitmap_t icon32_folder, icon32_file, icon32_text, icon32_image, icon32_app, icon32_game,
    icon32_drive, icon32_settings, icon32_computer, icon32_terminal, icon32_help, icon32_shutdown,
    icon32_logo, icon32_tasks, icon32_info, icon32_warning, icon32_error, icon32_question, icon32_camera, icon32_sound;
// Mouse cursors (max 16 wide, max 20 tall), black outline + white fill style, hot spot set
extern const bitmap_t cursor_arrow, cursor_ibeam, cursor_busy, cursor_size_we, cursor_size_ns, cursor_size_nwse, cursor_move;
